package objects

func withHelp(s Schema, help map[string]string) Schema {
	for gi := range s.Groups {
		for fi := range s.Groups[gi].Fields {
			field := &s.Groups[gi].Fields[fi]
			text, ok := help[field.ID]
			if ok {
				field.Help = &text
			}
		}
	}
	return s
}

